const requiredFields = [
  "vorname",
  "nachname",
  "email",
  "Telefonnummer",
   "arbeit",
  "sprache",
  "Gehaltsvorstellung",
  "Eintrittstermin",
  "Berufserfahrung",
  "Selbstbeschreibung"
];

const missingFields = requiredFields.filter(
  field => !$json.body[field]
);

return [{
  json: {
    ...$json,
    valid: missingFields.length === 0,
    missingFields
  },
  binary: $binary
}];

return [
  {
    json: $json,
    binary: {
      data: {
        ...$binary.data,
        fileName: "index.html",
        mimeType: "text/html"
      }
    }
  }
];

